        var options = new StackPanel(); var popup = new Popup { PlacementTarget = button, Placement = PlacementMode.Bottom, VerticalOffset = 4, StaysOpen = false, AllowsTransparency = true };
        foreach (var choice in choices) { string selected = choice; var item = new Button { Content = selected, Height = 33, MinWidth = 0, Margin = new Thickness(2), Padding = new Thickness(10, 0, 8, 0), HorizontalContentAlignment = HorizontalAlignment.Left, Background = Brush(selected == label ? "#34204D" : "#1B152B"), BorderBrush = Brush("#1B152B"), Foreground = Brush("#EDE2F7") }; item.Click += (s, e) => { popup.IsOpen = false; onSelect(selected); }; options.Children.Add(item); }
