    List<CommunityTrainer> VisibleCommunityTrainers()
    {
        IEnumerable<CommunityTrainer> items = communityTrainers;
        if (!String.IsNullOrWhiteSpace(communitySearch)) { string q = communitySearch.Trim(); items = items.Where(x => new[] { x.name, x.game, x.creator, x.description }.Any(v => !String.IsNullOrEmpty(v) && v.IndexOf(q, StringComparison.OrdinalIgnoreCase) >= 0)); }
        if (communityGame != "All Games") items = items.Where(x => String.Equals(x.game, communityGame, StringComparison.OrdinalIgnoreCase));
        if (communityType != "All Types") items = items.Where(x => String.Equals(x.type, communityType, StringComparison.OrdinalIgnoreCase));
        items = communitySort == "Name A–Z" ? items.OrderBy(x => x.name, StringComparer.OrdinalIgnoreCase) : items.OrderByDescending(x => CommunityDate(x.updatedAt));
        return items.ToList();
    }
    DateTime CommunityDate(string value) { DateTime date; return DateTime.TryParse(value, out date) ? date : DateTime.MinValue; }

    void RenderCommunityLists()
