        if (communityTab == "Trending") { communityFeatured.Children.Add(CommunityEmpty("Trending needs download history", "GitHub does not provide weekly trend history. This section will appear when the catalog includes verified snapshots.")); return; }
        if (communityTab == "Popular") { communityFeatured.Children.Add(CommunityEmpty("Popularity needs verified counts", "The catalog does not contain reliable trainer download counts yet. Browse and Latest show every published profile.")); return; }
        if (communityTab == "Following") { communityFeatured.Children.Add(CommunityEmpty("Following is not connected yet", "You can browse creators and their repositories below while local creator follows are being built.")); return; }
        if (communityTab == "My Uploads") { communityFeatured.Children.Add(CommunityEmpty("Submit your trainer for review", "Fork Alter, add your trainer entry to the catalog, and open a pull request. Your work stays in your own repository.")); var share = Button("Start a pull request  ↗", () => OpenUrl(CommunityPullRequest), true); share.Background = Brush("#5B239E"); communityFeatured.Children.Add(share); return; }
        var heading = Copy(communityTab == "Browse" ? "Featured Trainers" : communityTab == "Latest" ? "Latest Trainers" : "Community Trainers", 18, "#F4EBFB"); heading.FontWeight = FontWeights.SemiBold; communityFeatured.Children.Add(heading);
