    void RenderCommunitySidebar()
    {
        if (communityNews == null) return; communityNews.Children.Clear(); communityCreators.Children.Clear(); communityGames.Children.Clear();
        var top = new Grid(); top.ColumnDefinitions.Add(new ColumnDefinition()); top.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(74) }); var newsTitle = Copy("Community News", 16, "#F4EBFB"); newsTitle.FontWeight = FontWeights.SemiBold; top.Children.Add(newsTitle); var view = Button("View all  →", () => OpenUrl(CommunityDiscussions), false); view.Height = 29; view.MinWidth = 0; view.Margin = new Thickness(0); view.Padding = new Thickness(7, 0, 7, 0); view.Background = Brush("#1A142B"); view.BorderBrush = Brush("#49345F"); Grid.SetColumn(view, 1); top.Children.Add(view); communityNews.Children.Add(top);
