        var update = Button("Refresh news  ↻", () => RefreshCommunity(), false); update.Height = 32; update.MinWidth = 0; update.Margin = new Thickness(0, 8, 0, 0); update.Background = Brush("#171226"); update.BorderBrush = Brush("#3F2B54"); communityNews.Children.Add(update);
