    Border CommunityNewsCard(string title, string excerpt, string updated, string category, string url) { var grid = new Grid(); grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(48) }); grid.ColumnDefinitions.Add(new ColumnDefinition()); var tile = new Border { Width = 40, Height = 40, CornerRadius = new CornerRadius(9), Background = Brush("#28173F"), Child = Glyph(category == "Release" ? "star" : "community", 23, "#BB86E5"), VerticalAlignment = VerticalAlignment.Top }; grid.Children.Add(tile); var text = new StackPanel { Margin = new Thickness(7, 0, 0, 0) }; var heading = Copy(title ?? "Community update", 12, "#EFE7F7"); heading.FontWeight = FontWeights.SemiBold; text.Children.Add(heading); text.Children.Add(Copy((category ?? "Discussion") + " · " + (CommunityDate(updated) == DateTime.MinValue ? "Recently" : CommunityDate(updated).ToString("MMM d, yyyy")), 10, "#9E88AF")); if (!String.IsNullOrWhiteSpace(excerpt)) { var summary = Copy(excerpt, 11, "#B6A8C4"); summary.MaxHeight = 48; text.Children.Add(summary); } Grid.SetColumn(text, 1); grid.Children.Add(text); var button = Button(title, () => OpenUrl(url), false); button.Content = grid; button.Height = Double.NaN; button.MinWidth = 0; button.HorizontalContentAlignment = HorizontalAlignment.Stretch; button.Margin = new Thickness(0, 9, 0, 0); button.Padding = new Thickness(8, 10, 8, 10); button.Background = Brush("#121020"); button.BorderBrush = Brush("#2B223A"); var card = new Border { Child = button }; return card; }
    string ReleaseExcerpt(string body) { if (String.IsNullOrWhiteSpace(body)) return "Read the release notes on GitHub."; string plain = Regex.Replace(body, @"[#>*_`\[\]()]", " "); plain = Regex.Replace(plain, @"\s+", " ").Trim(); return plain.Length > 125 ? plain.Substring(0, 122) + "…" : plain; }
    bool CommunityDiscussionLink(string link) { Uri uri; return Uri.TryCreate(link, UriKind.Absolute, out uri) && uri.Scheme == "https" && uri.Host.Equals("github.com", StringComparison.OrdinalIgnoreCase) && uri.AbsolutePath.StartsWith("/an1dxsh/Alter/discussions/", StringComparison.OrdinalIgnoreCase); }

    async void RefreshCommunity()
    {
        if (communityLoading) return; communityLoading = true; communityMessage = "Checking GitHub for updates…"; if (communityStatus != null) communityStatus.Text = communityMessage;
        try
        {
            var result = await Task.Run(() => { var local = ReadCommunityCatalog(Path.Combine(root, "community", "catalog.json")); var cache = ReadCommunityCatalog(Path.Combine(root, "community", "cache.json")); var localNews = ReadCommunityNews(Path.Combine(root, "community", "discussions.json")); var cachedNews = ReadCommunityNews(Path.Combine(root, "community", "discussions-cache.json")); CommunityCatalog online = null; CommunityNewsFeed onlineNews = null; List<CommunityRelease> releases = null; try { online = ParseCommunityCatalog(FetchCommunityText(CommunityCatalogUrl, 2 * 1024 * 1024)); } catch { } try { onlineNews = ParseCommunityNews(FetchCommunityText(CommunityNewsUrl, 512 * 1024)); } catch { } try { releases = ProfileJson().Deserialize<List<CommunityRelease>>(FetchCommunityText(CommunityReleasesUrl, 2 * 1024 * 1024)); } catch { } return new { Catalog = online ?? cache ?? local, Online = online != null, News = onlineNews ?? cachedNews ?? localNews, OnlineNews = onlineNews != null, Releases = releases }; });
            communityTrainers = CleanCommunityCatalog(result.Catalog); communityPosts = (result.News == null ? new List<CommunityPost>() : result.News.posts).Where(x => x != null && !String.IsNullOrWhiteSpace(x.title) && CommunityDiscussionLink(x.url)).Take(20).ToList(); communityReleases = (result.Releases ?? new List<CommunityRelease>()).Where(x => CommunityLink(x.html_url)).ToList(); communityLoaded = true;
            if (result.Online) { try { Directory.CreateDirectory(Path.Combine(root, "community")); File.WriteAllText(Path.Combine(root, "community", "cache.json"), ProfileJson().Serialize(result.Catalog)); } catch { } }
            if (result.OnlineNews) { try { Directory.CreateDirectory(Path.Combine(root, "community")); File.WriteAllText(Path.Combine(root, "community", "discussions-cache.json"), ProfileJson().Serialize(result.News)); } catch { } }
            communityMessage = result.Online ? "Catalog updated from GitHub" : communityTrainers.Count > 0 ? "Offline · showing saved catalog" : "No published trainers yet · local tools still work";
            communityLoading = false; if (body.Children.Contains(communityScroll)) CommunityHubPage();
        }
        catch (Exception ex) { communityLoaded = true; communityMessage = "Community unavailable: " + ex.Message; if (communityStatus != null) communityStatus.Text = communityMessage; }
        finally { communityLoading = false; }
    }
    CommunityCatalog ReadCommunityCatalog(string path) { try { return File.Exists(path) ? ParseCommunityCatalog(File.ReadAllText(path)) : null; } catch { return null; } }
    CommunityCatalog ParseCommunityCatalog(string json) { var data = ProfileJson().Deserialize<CommunityCatalog>(json); return data != null && data.trainers != null ? data : null; }
    CommunityNewsFeed ReadCommunityNews(string path) { try { return File.Exists(path) ? ParseCommunityNews(File.ReadAllText(path)) : null; } catch { return null; } }
    CommunityNewsFeed ParseCommunityNews(string json) { var data = ProfileJson().Deserialize<CommunityNewsFeed>(json); return data != null && data.posts != null ? data : null; }
    List<CommunityTrainer> CleanCommunityCatalog(CommunityCatalog catalog) { return (catalog == null ? new List<CommunityTrainer>() : catalog.trainers).Where(x => x != null && !String.IsNullOrWhiteSpace(x.name) && !String.IsNullOrWhiteSpace(x.game) && CommunityLink(x.repository)).GroupBy(x => x.id ?? x.repository, StringComparer.OrdinalIgnoreCase).Select(x => x.First()).Take(500).ToList(); }
    bool CommunityLink(string link) { Uri uri; return Uri.TryCreate(link, UriKind.Absolute, out uri) && uri.Scheme == "https" && uri.Host.Equals("github.com", StringComparison.OrdinalIgnoreCase); }
    string FetchCommunityText(string url, int maximum) { ServicePointManager.SecurityProtocol = SecurityProtocolType.Tls12; var request = (HttpWebRequest)WebRequest.Create(url); request.UserAgent = "Alter Community/0.1"; request.Accept = "application/vnd.github+json"; request.Timeout = 8000; request.ReadWriteTimeout = 8000; using (var response = (HttpWebResponse)request.GetResponse()) using (var stream = response.GetResponseStream()) using (var memory = new MemoryStream()) { var buffer = new byte[8192]; int read; while ((read = stream.Read(buffer, 0, buffer.Length)) > 0) { if (memory.Length + read > maximum) throw new InvalidDataException("Community response is too large."); memory.Write(buffer, 0, read); } return Encoding.UTF8.GetString(memory.ToArray()); } }
    async void OpenCommunityEntry(CommunityTrainer entry)
    {
        if (String.IsNullOrWhiteSpace(entry.profileUrl)) { OpenUrl(entry.repository); return; }
        Uri uri; if (!Uri.TryCreate(entry.profileUrl, UriKind.Absolute, out uri) || uri.Scheme != "https" || !(uri.Host.Equals("raw.githubusercontent.com", StringComparison.OrdinalIgnoreCase) || uri.Host.Equals("github.com", StringComparison.OrdinalIgnoreCase)) || !Regex.IsMatch(entry.sha256 ?? "", "^[a-fA-F0-9]{64}$")) { MessageBox.Show("This entry needs a GitHub HTTPS profile URL and a SHA-256 checksum. Open its repository to review it.", "Alter community"); OpenUrl(entry.repository); return; }
        if (MessageBox.Show("Import " + entry.name + " by " + entry.creator + "?\n\nSource: " + entry.repository + "\n\nAlter will verify the checksum before adding this profile. Review any scripts before enabling them.", "Import community trainer", MessageBoxButton.YesNo) != MessageBoxResult.Yes) return;
        try
        {
            var bytes = await Task.Run(() => { var request = (HttpWebRequest)WebRequest.Create(uri); request.UserAgent = "Alter Community/0.1"; request.Timeout = 10000; request.ReadWriteTimeout = 10000; using (var response = request.GetResponse()) using (var stream = response.GetResponseStream()) using (var memory = new MemoryStream()) { var buffer = new byte[8192]; int read; while ((read = stream.Read(buffer, 0, buffer.Length)) > 0) { if (memory.Length + read > 4 * 1024 * 1024) throw new InvalidDataException("Trainer profile exceeds 4 MB."); memory.Write(buffer, 0, read); } return memory.ToArray(); } });
            string hash; using (var sha = SHA256.Create()) hash = BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-", ""); if (!hash.Equals(entry.sha256, StringComparison.OrdinalIgnoreCase)) throw new InvalidDataException("Checksum mismatch. The profile was not imported.");
            var profile = ProfileJson().Deserialize<Profile>(Encoding.UTF8.GetString(bytes)); if (profile == null || String.IsNullOrWhiteSpace(profile.name) || String.IsNullOrWhiteSpace(profile.process)) throw new InvalidDataException("Invalid Alter trainer profile."); profile.id = Guid.NewGuid().ToString("N"); profile.cheats = (profile.cheats ?? new List<Feature>()).Where(f => f != null && ((f.kind == "value" && !String.IsNullOrWhiteSpace(f.address) && (f.dataType == "Int32" || f.dataType == "Float" || f.dataType == "Double")) || (f.kind == "script" && !String.IsNullOrWhiteSpace(f.name)))).ToList(); foreach (var feature in profile.cheats) { feature.id = Guid.NewGuid().ToString("N"); feature.trusted = false; feature.freeze = false; }
            profile.externalTrainer = null; SaveProfile(profile); Load(); MessageBox.Show("Imported " + profile.name + ". Review its features in Library before using it.", "Alter community"); Library();
        }
        catch (Exception ex) { MessageBox.Show(ex.Message, "Community import failed"); }
    }
}
